function [u_c_ref_ab_out, w] = mfun_gfm_modulate(fbk_in, u_c_in, p)
%MFUN_GFM_MODULATE Block modulate of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the Simulink model, which adds its folder to the MATLAB
%   path. The parameters are the fields of the struct p (from the mask, [] as NaN).
fbk = gfm_feedbacks_unpack(fbk_in);
u_c = complex_in(u_c_in);
% Voltage reference in stationary coordinates, its angle advanced by
% k_comp*T_s*w_c (k_comp = 1.5 of the controller)
u_c_ref_ab = exp(1i*fbk.theta_c)*u_c;
u_c_ref_ab = u_c_ref_ab*exp(1i*1.5*p.T_s*fbk.w_c);
w = fbk.w_c;
u_c_ref_ab_out = complex_out(u_c_ref_ab);
end

function s = gfm_feedbacks_unpack(u)
%GFM_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_c_zoh', complex(u(5), u(6)), ...
    'v_c', complex(u(7), u(8)), ...
    'u_g', complex(u(9), u(10)), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'theta_c', u(13), ...
    'w_c', u(14));
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end
